import React, { useState, useEffect } from 'react';
import './MonCompte.css';
import VerifierPin from './VerifierPin';

function MonCompte({ allerVers, utilisateur, setUtilisateur }) {
  const [nomArtiste, setNomArtiste] = useState('');
  const [bio, setBio] = useState('');
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);
  const [pinVerifie, setPinVerifie] = useState(false);

  useEffect(() => {
    if (utilisateur) {
      setNomArtiste(utilisateur.nom_artiste || utilisateur.prenom);
      setBio(utilisateur.bio || '');
      setPhotoPreview(utilisateur.photo_profil || null);
    }
  }, [utilisateur]);

  const handlePhoto = (e) => {
    const fichier = e.target.files[0];
    setPhoto(fichier);
    setPhotoPreview(URL.createObjectURL(fichier));
  };

  const handleSauvegarder = async () => {
    setChargement(true);
    setMessage('');

    try {
      const formData = new FormData();
      formData.append('utilisateur_id', utilisateur.id);
      formData.append('nom_artiste', nomArtiste);
      formData.append('bio', bio);
      if (photo) formData.append('photo', photo);

      const reponse = await fetch('/api/profil/modifier', {
        method: 'PUT',
        body: formData
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        setMessage('✅ Profil mis à jour !');
        const nouvelUtilisateur = { ...utilisateur, ...donnees.utilisateur };
        localStorage.setItem('utilisateur', JSON.stringify(nouvelUtilisateur));
        setUtilisateur(nouvelUtilisateur);
      } else {
        setMessage('❌ ' + donnees.message);
      }
    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  if (!pinVerifie) {
    return (
      <VerifierPin
        utilisateur={utilisateur}
        titre="Accès Mon Compte"
        onSuccess={() => setPinVerifie(true)}
        onCancel={() => allerVers('accueil')}
      />
    );
  }

  return (
    <div className="compte-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">👋 {utilisateur?.prenom}</span>
          <button className="btn-dashboard" onClick={() => allerVers('dashboard')}>
            🎛️ Dashboard
          </button>
          <button className="btn-login" onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('utilisateur');
            allerVers('accueil');
          }}>Déconnexion</button>
        </div>
      </header>

      <div className="compte-contenu">
        <h1 className="compte-titre">⚙️ Mon Compte</h1>

        <div className="compte-grid">
          <div className="compte-gauche">
            <div className="photo-section">
              <div className="photo-cercle">
                {photoPreview ? (
                  <img src={photoPreview} alt="Profil" />
                ) : (
                  <div className="photo-defaut">🎤</div>
                )}
              </div>
              <label className="btn-photo">
                📷 Changer la photo
                <input type="file" accept="image/*" onChange={handlePhoto} hidden />
              </label>
            </div>

            <button
              className="btn-voir-profil"
              onClick={() => allerVers('profil_' + utilisateur.id)}
            >
              👁 Voir mon profil public
            </button>
          </div>

          <div className="compte-droite">
            {message && <div className="compte-message">{message}</div>}

            <div className="compte-champ">
              <label>Nom d'artiste</label>
              <input
                type="text"
                placeholder="Votre nom d'artiste"
                value={nomArtiste}
                onChange={(e) => setNomArtiste(e.target.value)}
              />
            </div>

            <div className="compte-champ">
              <label>Bio</label>
              <textarea
                placeholder="Parlez de vous à vos fans..."
                value={bio}
                onChange={(e) => setBio(e.target.value)}
                rows={4}
              />
            </div>

            <div className="compte-champ">
              <label>Téléphone</label>
              <input
                type="text"
                value={utilisateur?.telephone}
                disabled
                className="input-disabled"
              />
            </div>

            <div className="compte-champ">
              <label>Rôle</label>
              <input
                type="text"
                value={utilisateur?.role}
                disabled
                className="input-disabled"
              />
            </div>

            <button
              className="compte-btn"
              onClick={handleSauvegarder}
              disabled={chargement}
            >
              {chargement ? 'Sauvegarde...' : '💾 Sauvegarder'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default MonCompte;
